package com.bookreads.storage

import androidx.datastore.core.okio.OkioSerializer
import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json
import okio.BufferedSink
import okio.BufferedSource

internal object AppPreferencesSerializer : OkioSerializer<AppPreferences> {
    override val defaultValue = AppPreferences()

    override suspend fun readFrom(source: BufferedSource): AppPreferences =
        try {
            Json.decodeFromString(source.readUtf8())
        } catch (e: Exception) {
            AppPreferences()
        }

    override suspend fun writeTo(
        t: AppPreferences,
        sink: BufferedSink,
    ) {
        sink.writeUtf8(Json.encodeToString(t))
    }
}
```

