package com.bookreads.storage

import kotlinx.serialization.encodeToString
import kotlinx.serialization.json.Json

class PrefServiceLocalStorage : LocalStorageService {
    override suspend fun getUsername(): String? = getLocalStorageItem(KEY_USERNAME)

    override suspend fun saveUsername(username: String) {
        setLocalStorageItem(KEY_USERNAME, username)
    }

    override suspend fun getActiveSession(): SessionData? {
        val json = getLocalStorageItem(KEY_SESSION) ?: return null
        return try {
            Json.decodeFromString<SessionData>(json)
        } catch (e: Exception) {
            null
        }
    }

    override suspend fun saveActiveSession(data: SessionData) {
        setLocalStorageItem(KEY_SESSION, Json.encodeToString(data))
    }

    override suspend fun clearActiveSession() {
        removeLocalStorageItem(KEY_SESSION)
    }

    companion object {
        private const val KEY_USERNAME = "bookreads_username"
        private const val KEY_SESSION = "bookreads_session"
    }
}
```

