package com.bookreads.storage

@JsFun("(key) => localStorage.getItem(key) ?? null")
private external fun getItemJs(key: JsString): JsString?

@JsFun("(key, value) => localStorage.setItem(key, value)")
private external fun setItemJs(
    key: JsString,
    value: JsString,
)

@JsFun("(key) => localStorage.removeItem(key)")
private external fun removeItemJs(key: JsString)

internal actual fun getLocalStorageItem(key: String): String? =
    getItemJs(key.toJsString())?.toString()

internal actual fun setLocalStorageItem(
    key: String,
    value: String,
) {
    setItemJs(key.toJsString(), value.toJsString())
}

internal actual fun removeLocalStorageItem(key: String) {
    removeItemJs(key.toJsString())
}
